apiVersion: argoproj.io/v1alpha1
kind: Application

metadata:
  name: backend-api

spec:

  project: default

  source:
    repoURL: https://github.com/example/gitops
    targetRevision: main
    path: apps/backend

  destination:
    server: https://kubernetes.default.svc
    namespace: backend

  syncPolicy:
    automated:
      prune: true
      selfHeal: true

    syncOptions:
      - CreateNamespace=true
